-- 取回 sorted
WITH "base" AS (SELECT "ds_orders"."Row ID" AS "f_row_id", "ds_orders"."Order ID" AS "f_order_id", "ds_orders"."Order Date" AS "f_order_date", "ds_orders"."Ship Date" AS "f_ship_date", "ds_orders"."Ship Mode" AS "f_ship_mode", "ds_orders"."Customer ID" AS "f_customer_id", "ds_orders"."Customer Name" AS "f_customer_name", "ds_orders"."Segment" AS "f_segment", "ds_orders"."Country/Region" AS "f_country_region", "ds_orders"."City" AS "f_city", "ds_orders"."State/Province" AS "f_state_province", "ds_orders"."Postal Code" AS "f_postal_code", "ds_orders"."Region" AS "f_region", "ds_orders"."Product ID" AS "f_product_id", "ds_orders"."Category" AS "f_category", "ds_orders"."Sub-Category" AS "f_sub_category", "ds_orders"."Product Name" AS "f_product_name", "ds_orders"."Sales" AS "f_sales", "ds_orders"."Quantity" AS "f_quantity", "ds_orders"."Discount" AS "f_discount", "ds_orders"."Profit" AS "f_profit" FROM "SALES"."ds_orders" "ds_orders"), "src" AS (SELECT * FROM "base" WHERE ("f_country_region" IN ('United States'))), "topn_agg" AS (SELECT "f_region" AS "__k0", SUM("f_sales") AS "__a0" FROM "src" GROUP BY "f_region"), "topn" AS (SELECT "__k0" AS "__member" FROM "topn_agg" ORDER BY "__a0" DESC NULLS LAST, "__k0" ASC FETCH FIRST 3 ROWS ONLY), "dimf" AS (SELECT * FROM "src" WHERE ("f_category" IN ('Furniture', 'Technology')) AND EXISTS(SELECT 1 FROM "topn" WHERE DECODE("topn"."__member", "f_region", 1, 0) = 1)), "agg" AS (SELECT "f_region" AS "__k0", "f_category" AS "__k1", SUM("f_sales") AS "__a0" FROM "dimf" GROUP BY "f_region", "f_category"), "meas" AS (SELECT "agg".*, "__a0" AS "__m0" FROM "agg"), "sort_agg" AS (SELECT "f_region" AS "__k0", SUM("f_sales") AS "__a0" FROM "dimf" GROUP BY "f_region"), "sort" AS (SELECT "__k0" AS "__key", "__a0" AS "__v" FROM "sort_agg"), "sorted" AS (SELECT "m".*, "s0"."__v" AS "__sort0" FROM "meas" "m" LEFT JOIN "sort" "s0" ON DECODE("s0"."__key", "m"."__k0", 1, 0) = 1) SELECT * FROM "sorted"
